const configuredRoot = env.get('ACSM_PROJECT_ROOT');
const root = configuredRoot || 'C:\\bkp\\estagio doutoral\\Implementa\u00e7\u00e3o ACSM PPU\\acsm-main';
const separator = root.includes('\\') ? '\\' : '/';
msg.filename = root.replace(/[\\\/]+$/, '') + separator + 'resources' + separator + 'cps1' + separator + 'datasheet.pdf';
return msg;

if (msg.error) {
    msg.statusCode = 404;
    msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
    msg.payload = JSON.stringify({ error: 'Datasheet not available' });
    return msg;
}

msg.statusCode = 200;
msg.headers = {
    'Content-Type': 'application/pdf',
    'Content-Disposition': 'inline; filename="cps1-datasheet.pdf"'
};
return msg;

